program:
root = Stack([header, summaryGrid, clientTabs], 16)
header = Text("Client Directory", "heading")

summaryGrid = Grid([totalCard, missingDocsCard, docsRatioCard], 3, 16)
totalCard = Surface([totalStat], "Total Portfolio")
totalStat = Stat("Total Clients", dash.clientsTotal, "number", null, "accent")

missingDocsCard = Surface([missingStat], "Attention Required")
missingStat = Stat("Missing Documents", dash.clientsMissingDocs, "number", null, "danger")

docsRatioCard = Surface([docsStat], "Outstanding Docs")
docsStat = Stat("Total Outstanding", dash.documentsOutstanding, "number")

dash = Query("host_getDashboard", {}, {"clientsTotal": 0, "clientsMissingDocs": 0, "documentsOutstanding": 0, "documentsReceived": 0})

clientTabs = Tabs([allTab, missingTab])
allTab = {label: "All Clients", content: allCard}
missingTab = {label: "Missing Documents", content: missingCard}

allCard = Surface([allTable], "Client Roster")
allTable = DataTable(clients, cols, "filingDeadline asc")

missingCard = Surface([missingTable], "Clients Pending Documents")
missingTable = DataTable(missingClients, cols, "filingDeadline asc")

clients = Query("host_listClients", {}, [])
missingClients = Query("host_listClients", {filter: "missing_docs"}, [])

cols = [c1, c2, c3, c4, c5, c6]
c1 = {key: "businessName", label: "Business Name"}
c2 = {key: "entityType", label: "Entity Type", format: "label"}
c3 = {key: "contactName", label: "Contact"}
c4 = {key: "contactEmail", label: "Email"}
c5 = {key: "filingDeadline", label: "Filing Deadline", format: "date"}
c6 = {key: "status", label: "Status", format: "label"}
